import { Suspense } from 'react'
import { CardStatsWrapper } from './CardStatsWrapper'
import { RevenueChartWrapper } from './RevenueChartWrapper'
import { LatestInvoicesWrapper } from './LatestInvoicesWrapper'

function CardStatsFallback() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>Loading...</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>Loading...</p>
      </div>
    </div>
  )
}

function RevenueChartFallback() {
  return (
    <div className="chart">
      <h2>Revenue</h2>
      <p>Loading...</p>
    </div>
  )
}

function LatestInvoicesFallback() {
  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <p>Loading...</p>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsFallback />}>
        <CardStatsWrapper />
      </Suspense>
      <Suspense fallback={<RevenueChartFallback />}>
        <RevenueChartWrapper />
      </Suspense>
      <Suspense fallback={<LatestInvoicesFallback />}>
        <LatestInvoicesWrapper />
      </Suspense>
    </main>
  )
}

